test_company_construction_rejects_bad_documentation_parent_shape_and_level_type[ai_construction_targets = { building_missing = { level = 5 state_trigger = { state_region = s:STATE_KNOWN } } }-# While the AI is trying to form a company (that has passed the ai_will_do, potential and attainable triggers) it will have increased weight for certain building types in certain states, which buildings, which states (determined through a trigger) and up to which level are all specified here
# Note that scripting this with an empty state trigger will do nothing, as it would otherwise result in indiscrimate construction in all states!
company_key = { ai_construction_targets = { building_iron_mine = {
level = 5
state_trigger = { state_region = s:STATE_NORRLAND }
} } }
]

